#' Cumulative Periodogram 
#'
#' Generates a \code{ggplot} object that produces a cumulative periodogram of
#' the regARIMA residuals extracted from \code{seas_obs}.
#' The plot optionally includes a 45 degree reference line. This package uses the 
#' \code{ggfortify} package \insertCite{ggfortify2016}{blsplotGG}.
#'
#' Version 1.7, 2026-10-28
#'
#' @param seas_obj \code{seas} object for a single series generated by the
#'        \code{seasonal} package \insertCite{seasonal2018}{blsplotGG}.
#'        This is a required entry.
#' @param main_title Title for the plot. 
#'        Default is \code{"Cumulative Periodogram"}.
#' @param sub_title Subtitle for the plot. Optional entry.
#' @param this_x_label Label for X-axis.  Default is no label for the X-axis.
#' @param this_y_label Label for Y-axis.  Default is no label for the Y-axis.
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines. 
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param line_color Character vector of length 3; color used for lines in the plot,
#'        in the order of periodogram, lower limit, upper limit.
#'        Default is \code{c("blue", "red", "red")}.
#' @param reference_color Character string; color used for reference line in the plot.
#'        Default is \code{"grey"}.
#' @param line_label Character vector of length 3; labels used for lines in the plot,
#'        in the order of periodogram, lower limit, upper limit. 
#'        Default is \code{c("Cpgrm", "Lower", "Upper")}.
#' @param this_legend_title Title for legend.  Default is \code{"Series"}
#' @param this_legend_title_size integer scalar; Size of the legend title.
#'        Must be greater than zero.
#'        Default is \code{12}.
#' @param this_legend_text_size integer scalar; Size of the legend title.
#'        Must be greater than zero.
#'        Default is \code{10}.
#' @param this_legend_position Character string; indicates the position of the plot legend.
#'        Possible values are \code{"right"}, \code{"left"}, \code{"top"}, 
#'        \code{"bottom"}, and \code{"none"}
#'        Default is \code{"right"}.
#' @param this_legend_space integer scalar; Space between legend and plot in points.
#'        Must be greater than or equal to zero.
#'        Default is \code{10}.
#' @return A \code{ggplot} object that generates a cumulative periodogram.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' air_seas <- 
#'     seasonal::seas(AirPassengers, x11="",
#'                    arima.model = "(0 1 1)(0 1 1)")
#' air_cpgrm <- 
#'    plot_cumulative_periodogram(air_seas,
#'       sub_title = "Airline Passengers, regARIMA residuals",
#'       reference_color = "steelblue",
#'       this_legend_title_size = 8,
#'       this_legend_text_size = 6,
#'       this_legend_position = "bottom",
#'       this_legend_space = 0)
#' @importFrom rlang .data
#' @importFrom magrittr %>%
#' @importFrom Rdpack reprompt
#' @export
plot_cumulative_periodogram <- 
    function(seas_obj = NULL, 
             main_title = "Cumulative Periodogram", 
             sub_title = NULL, 
             this_x_label = NULL, 
             this_y_label = NULL, 
             do_grid = FALSE,
             do_background = FALSE,
             line_color = c("blue", "red", "red"), 
             reference_color = "grey",
             line_label = c("Cpgrm", "Lower", "Upper"),
             this_legend_title = "Series",
			 this_legend_title_size = 12,
			 this_legend_text_size = 10,
			 this_legend_position = "right",
			 this_legend_space = 10) {
    # Author: Brian C. Monsell (OEUS) Version 1.7, 2026-10-28

    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        cat("must specify a seas object")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
            cat("First argument must be a seas object")
			return(NULL)
        }
    }

	# check legend options 
	position_all <- c("top", "bottom", "left", "right")
	if (sum(match(position_all, this_legend_position), na.rm = TRUE) == 0) {
        cat(paste("Legend position choice not valid:", this_legend_position))
		return(NULL)
	}
	
    # check if values of \code{this_legend_text_size}, \code{this_legend_title_size}, 
	# and \code{this_legend_space} are valid, return \code{NULL} if not.
	if (this_legend_text_size <= 0) {
        cat(paste("Legend text size not valid (must be greater than zero):", 
		           this_legend_text_size))
        return(NULL)
	}
	
	if (this_legend_title_size <= 0) {
        cat(paste("Legend title text size not valid (must be greater than zero):", 
		           this_legend_title_size))
        return(NULL)
	}
	
	if (this_legend_space < 0) {
        cat(paste("Legend space size not valid (must be greater than or equal to zero):", 
		           this_legend_space))
        return(NULL)
	}
	
	# extract regARIMA residual
	this_rsd <- seasonal::series(seas_obj, "rsd")

	# generate Cumulative periodogram
	rsd_cpgram <- 
		ggfortify::ggcpgram(this_rsd, 
			conf.int = TRUE, 
			conf.int.colour = line_color[2], 
			conf.int.linetype = "dashed")
	
	#reform x axis
	base_cpgram <- max(rsd_cpgram$data$x)
	x2 <- rsd_cpgram$data$x / base_cpgram
	
	# generate data frame for plot
	rfreq <- NULL
	cpgram_df <- data.frame(
		rfreq = x2,
		cpgram = rsd_cpgram$data$y,
		upper = rsd_cpgram$data$upper,
		lower = rsd_cpgram$data$lower) %>%
		dplyr::select(.data$rfreq, .data$cpgram, .data$lower, .data$upper) %>%
		tidyr::gather(key = "cpgrm", value = "value", -rfreq) # not finding x

	# Generate plot for Periodogram
	p_cpgram <- 
		ggplot2::ggplot(cpgram_df) + 
		ggplot2::geom_line(ggplot2::aes(x = .data$rfreq, 
                                        y = .data$value, 
                                        color = .data$cpgrm)) + 
		ggplot2::scale_color_manual(labels = line_label, 
                                    values = c("cpgram" = line_color[1],
                                               "lower"  = line_color[2],
                                               "upper"  = line_color[3]),
                                    breaks=c("cpgram", "lower", "upper")) +
		ggplot2::labs(title = main_title,
					  subtitle = sub_title,
                      x = this_x_label,
                      y = this_y_label) +
		ggplot2::guides(color = ggplot2::guide_legend(this_legend_title)) +
		ggplot2::geom_abline(intercept = 0, 
			slope = 1, 
			color = reference_color, 
			linetype = "dashed")

	# remove grey background if \code{do_background = FALSE} 
    if (!do_background) {
		p_cpgram <- p_cpgram + ggplot2::theme_bw()
    }

	# remove grid lines if \code{do_grid = FALSE}
	if (!do_grid) {
	    p_cpgram <- p_cpgram + 
		    ggplot2::theme(panel.grid.major = ggplot2::element_blank(), 
			               panel.grid.minor = ggplot2::element_blank())
	}

	# set up legend
	p_cpgram <- p_cpgram +
		ggplot2::theme(legend.text = ggplot2::element_text(size = this_legend_text_size),
			legend.title = ggplot2::element_text(size = this_legend_title_size),
			legend.position = this_legend_position,
			legend.box.spacing = ggplot2::unit(this_legend_space, "pt"))

	return(p_cpgram)
}